ALTER TABLE public.stores ADD COLUMN IF NOT EXISTS pickup_address TEXT; ALTER TABLE public.stores ADD COLUMN IF NOT EXISTS pickup_phone TEXT; CREATE TABLE IF NOT EXISTS public.pickup_address_changes (id UUID DEFAULT uuid_generate_v4() PRIMARY KEY, store_id UUID REFERENCES public.stores(id) ON DELETE CASCADE NOT NULL, old_address TEXT, new_address TEXT NOT NULL, reason TEXT NOT NULL, verified_phone TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW()); ALTER TABLE public.pickup_address_changes ENABLE ROW LEVEL SECURITY; CREATE POLICY "Store owners can view changes" ON public.pickup_address_changes FOR SELECT USING (store_id IN (SELECT id FROM public.stores WHERE user_id = auth.uid()));
